/*
 * Regenerates js/sample-data.js from the CSVs in data/.
 * Browsers can't read local files on their own, so the sample CSV text is embedded as strings.
 * Run with:  node tools/embed-data.js
 */
"use strict";
const fs = require("fs");
const path = require("path");
const root = path.join(__dirname, "..");
const read = (f) => fs.readFileSync(path.join(root, "data", f), "utf8");
const out =
  "/* Generated by tools/embed-data.js from data/*.csv. Don't edit by hand. All data is synthetic. */\n" +
  "(function (HI) {\n  \"use strict\";\n  HI.sampleData = {\n" +
  "    jobs: " + JSON.stringify(read("hireintercept_sample_jobs.csv")) + ",\n" +
  "    candidates: " + JSON.stringify(read("hireintercept_sample_candidates.csv")) + ",\n" +
  "    events: " + JSON.stringify(read("hireintercept_sample_events.csv")) + "\n" +
  "  };\n})(this.HI = this.HI || {});\n";
fs.writeFileSync(path.join(root, "js", "sample-data.js"), out);
console.log("Wrote js/sample-data.js");
